var tafStream = require("@taf/taf-stream");
var Cache = require("@taf/taf-dcache-helper");
var cacheShareProxy = Cache.cacheShareProxy.DCache; // 结构体定义

var cacheHelper = new Cache({
    moduleName: "TRomPool2",
    allowProxy: true
});

function cacheSucCallback(ret)
{
    console.log("cacheSucCallback: ", ret);
}

function cacheErrCallback(ret)
{
    console.log("cacheErrCallback: ", ret);
}

var map = new tafStream.Map(tafStream.String, cacheShareProxy.UpdateValue);
var updateValue1 = new cacheShareProxy.UpdateValue();
updateValue1.op = cacheShareProxy.Op.SET;
updateValue1.value = "yu";

var updateValue2 = new cacheShareProxy.UpdateValue();
updateValue2.op = cacheShareProxy.Op.SET;
updateValue2.value = "xi";

var updateValue3 = new cacheShareProxy.UpdateValue();
updateValue3.op = cacheShareProxy.Op.SET;
updateValue3.value = "122";

map.insert("key", updateValue1);
map.insert("ukey", updateValue2);
map.insert("value", updateValue3);
cacheHelper.insert('key', map, true, cacheSucCallback, cacheErrCallback);


setTimeout(function(){
    var vector = new tafStream.List(cacheShareProxy.Condition);
    var condition1 = new cacheShareProxy.Condition();
    condition1.fieldName = "key";
    condition1.op = cacheShareProxy.Op.EQ;
    condition1.value = "yu";
    vector.push(condition1);

    var condition2 = new cacheShareProxy.Condition();
    condition2.fieldName = "ukey";
    condition2.op = cacheShareProxy.Op.EQ;
    condition2.value = "xi";
    vector.push(condition2);

    cacheHelper.select("key", "key,ukey,value", vector, function(ret){
        var arr = ret.vtData.value;
        for(var i = 0; i < arr.length; i++)
        {
            var data = arr[i].value;
            console.log("data: ", data);
        }
    }, cacheErrCallback);

}, 1000);